import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';

@Component({
  selector: 'app-reporte-list',
  standalone: true,
  imports: [CommonModule, RouterModule],
  template: `<div class="container"><div class="header"><h2>Reportes Disponibles</h2></div><div class="info"><p>Reportes generados dinámicamente basados en datos de oportunidades:</p><ul><li><strong>Oportunidades por Fecha:</strong> GET /api/reportes/oportunidades/por-fecha?fecha_inicio=2026-01-01&fecha_fin=2026-12-31</li><li><strong>Oportunidades por Gestor:</strong> GET /api/reportes/oportunidades/por-gestor/{{ '{' }}id{{ '}' }}</li><li><strong>Oportunidades Ganadas/Perdidas:</strong> GET /api/reportes/oportunidades/ganadas-perdidas</li></ul></div></div>`,
  styleUrls: ['./reporte-list.component.css'],
})
export class ReporteListComponent {}
